"use client";

import "./aspect-ratio.css";
import type React from "react";
import { cn } from "tailwind-variants";
import { aspectRatioVariants, type AspectRatioVariants } from "./aspect-ratio.variants";

export type AspectRatioProps = {
  /**
   * The desired aspect ratio (width / height).
   * @default 16 / 9
   */
  ratio?: number;
} & AspectRatioVariants & React.ComponentProps<"div">;

export const AspectRatioRoot = ({
  children,
  className,
  ratio = 16 / 9,
  style,
  ...props
}: AspectRatioProps) => {
  const slots = aspectRatioVariants();

  return (
    <div
      className={cn(slots.root(), className)}
      style={{ aspectRatio: `${ratio}`, ...style }}
      {...props}
    >
      {children}
    </div>
  );
};

export const AspectRatio = AspectRatioRoot;

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const aspectRatioVariants = tv({
  slots: {
    root: "aspect-ratio",
  },
  variants: {},
  defaultVariants: {},
});

export type AspectRatioVariants = VariantProps<typeof aspectRatioVariants>;

import { AspectRatio, AspectRatioRoot } from "./aspect-ratio";

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/aspect-ratio/content.md
 */
export const AspectRatioContainer = {
  Root: AspectRatioRoot,
};

export { AspectRatio, AspectRatioRoot };

export type { AspectRatioProps } from "./aspect-ratio";
export { type AspectRatioVariants, aspectRatioVariants } from "./aspect-ratio.variants";
